/* /assets/wp-content/plugins/accessible-poetry/assets/css/main.css */

.material-icons {
    font-family: 'Material Icons';
    font-weight: normal;
    font-style: normal;
    font-size: 24px;
    display: inline-block;
    line-height: 1;
    text-transform: none;
    letter-spacing: normal;
    word-wrap: normal;
    white-space: nowrap;
    direction: ltr;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    -moz-osx-font-smoothing: grayscale;
    font-feature-settings: 'liga';
}
.awp-close-icon {
    display: block;
    width: 24px;
    height: 24px;
    position: relative;
}
.awp-close-icon:before,
.awp-close-icon:after {
    content: '';
    display: block;
    width: 100%;
    height: 2px;
    background-color: #fff;
    position: absolute;
    top: 14px;
}
.awp-close-icon:before {
    transform: rotate(45deg);
}
.awp-close-icon:after {
    transform: rotate(-45deg);
}
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

/* Reset box sizing for the toolbar */
#acwp-toolbar * {
	box-sizing: border-box;
	-webkit-box-sizing: border-box;
	-ms-box-sizing: border-box;
	-moz-box-sizing: border-box;
	-o-box-sizing: border-box;
}

/* helpers */
.acwp-hide {
    display: none;
}

/* Primary toggle button */
#acwp-toolbar-btn-wrap {
    border: 1.5px solid #1E7AB9;
    z-index: 9500;
    position: fixed;
    margin-top: -100vh;
    /* top: 120px;
    left: 20px; */
    border-radius: 50%;
    -webkit-transition: all 1200ms ease;
       -moz-transition: all 1200ms ease;
        -ms-transition: all 1200ms ease;
         -o-transition: all 1200ms ease;
            transition: all 1200ms ease;
}
#acwp-toolbar-btn {
    margin:  0;
    padding: 0;
    cursor:  pointer;
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    background: none;
    border: 0;
    width: 48px;
    height: 48px;
    background: #1E7AB9;
    text-align: center;
    color: #fff;
    border: 4px solid #fff;
    border-radius:50%;
    -webkit-box-shadow: 6px 8px 16px rgba(0,0,0,0.2);
       -moz-box-shadow: 6px 8px 16px rgba(0,0,0,0.2);
        -ms-box-shadow: 6px 8px 16px rgba(0,0,0,0.2);
         -o-box-shadow: 6px 8px 16px rgba(0,0,0,0.2);
            box-shadow: 6px 8px 16px rgba(0,0,0,0.2);
}
#acwp-toolbar-btn.acwp-noanimation {
    -webkit-transition: none;
    -moz-transition: none;
    -ms-transition: none;
    -o-transition: none;
    transition: none;
}
/* Primary toggle button - Hover & focus modes */
#acwp-toolbar-btn:hover, 
#acwp-toolbar-btn:focus {
    border-color: orangered;
}

/* Primary toggle button - Active mode */
#acwp-toolbar-btn-wrap.show {
    margin-top: 0;
}

/* Primary toggle button - SVG Icon */
body.acwp-contrast #acwp-toolbar-btn svg,
#acwp-toolbar-btn svg {
    height: auto;
    display: inline-block;
    width: 36px;
    top: 2px;
    position: relative;
    background-color: transparent;
}

/* Primary toggle button - Right side */
#acwp-toolbar-btn-wrap.acwp-right {
    left: auto;
    right: 10px
}

/* Toolbar close button */
#acwp-close-toolbar {
    margin: 0;
    padding: 0;
    cursor: pointer;
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    background: none;
    border: 0;
    position: absolute;
    top: 10px;
    right: 10px;
    outline: none;
    color: #fff;
    z-index: 250;
}
#acwp-toolbar-module > #acwp-close-toolbar{
    color: #000;
    top: 0;
    right: 0;
}

/* Toolbar close button - Focus mode */
body.acwp-keyboard #acwp-close-toolbar:focus{
    border: 1px solid orangered;
}

/* Toolbar close button - Right side */
body.rtl #acwp-close-toolbar{
    right: auto;
    left: 10px
}
body.rtl #acwp-toolbar-module > #acwp-close-toolbar{
    color: #000;
    right: auto;
    left: 0;
}

/* Toolbar footer */
.acwp-footer {
    border-top:1px solid #efefef
}

/* Toolbar footer links */
.acwp-footer a {
    color: #3c8dbc;
    text-decoration: none;
}

/* Toolbar footer links - Focus & hover modes */
.acwp-footer a:hover, .acwp-footer a:focus {
    color: #3c8dbc;
    text-decoration: underline;
}

/* Toolbar footer list */
.acwp-footer ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

/**
 * Toolbar footer list
 * 
 * @style columns
 */
body.acwp-contrast #acwp-toolbar.acwp-style-columns .acwp-footer ul {
    background-color: #ccc;
}

/* Toolbar footer list item */
.acwp-footer ul li {
    margin: 0;
    padding: 8px 20px;
    line-height: 18px;
    font-size: 15px;
    border-bottom: 1px solid #efefef;
}
.acwp-footer ul li a {
    color: #333;
}
.acwp-footer ul li a:hover,
.acwp-footer ul li a:focus {
    text-decoration: underline;
    color: #333;
}
/* Toolbar footer list copyrights item */
.acwp-footer ul li:last-child {
    padding-bottom:0;
    border:0;
    background:#efefef;
    text-align:center;
    font-size:13px
}
.acwp-footer ul li:last-child i.material-icons{
    line-height:18px;
    font-size:13px;
    position:relative;
    top:2px
}

/**
 * Toolbar footer list item
 * 
 * @style columns
 */
#acwp-toolbar.acwp-style-columns .acwp-footer ul li {
    text-align: center;
    padding: 4px 12px;
    border-radius: 5px;
}

