/*++++++++++++++++++++
Moz Selection
++++++++++++++++++++++*/
:root {
	--primary-color: #2490eb;
	--primary-dark-color: #14457b;
	--dark-color: #18100f;
	--secondary-color: #666666;
	--grey-color: #f4f6f9;
	--white-color: #ffffff;
	--body-fonts: 'Montserrat', sans-serif;
	--title-fonts: 'Quicksand', sans-serif;
}

::-moz-selection {
	text-shadow: none;
	background: var(--primary-color);
	color: #fff;
}

::-moz-selection {
	text-shadow: none;
	background: var(--primary-color);
	color: #fff;
}

::selection {
	text-shadow: none;
	background: var(--primary-color);
	color: #fff;
}

/*+++++++++++++++++++++++++++++++++++++++++
General
++++++++++++++++++++++++++++++++++++++++*/
body {
	background: var(--white-color);
	font-family: var(--body-fonts);
	font-size: 1rem;
	font-style: normal;
	font-weight: normal;
	line-height: 2;
	color: var(--secondary-color);
	overflow-x: hidden;
}

h1,
h2,
h3,
h4,
h5,
h6 {
	font-family: var(--title-fonts);
	color: var(--dark-color);
	font-style: normal;
	text-transform: capitalize;
	font-weight: 600;
	margin: 0;
	-ms-word-wrap: break-word;
	word-wrap: break-word;
}

h1 a,
h2 a,
h3 a,
h4 a,
h5 a,
h6 a {
	color: inherit;
}

h1 {
	font-size: 40px;
	font-style: normal;
	line-height: 48px;
}

h2 {
	font-size: 36px;
	font-style: normal;
	line-height: 44px;
}

h3 {
	font-size: 32px;
	font-style: normal;
	line-height: 40px;
}

h4 {
	font-size: 28px;
	font-style: normal;
	line-height: 36px;
}

h5 {
	font-size: 24px;
	font-style: normal;
	line-height: 32px;
}

h6 {
	font-size: 20px;
	font-style: normal;
	line-height: 28px;
}

/*+++++++++++++ HTML Tags++++++++++++++*/
a,
.button {
	color: var(--primary-color);
	outline: none !important;
	transition: all 0.5s ease-in-out;
	transition: all 0.5s ease-in-out;
	-moz-transition: all 0.5s ease-in-out;
	-ms-transition: all 0.5s ease-in-out;
	-o-transition: all 0.5s ease-in-out;
	-webkit-transition: all 0.5s ease-in-out;
	text-decoration: none;
}

a:focus,
a:hover {
	color: var(--primary-color);
	outline: none;
	text-decoration: none !important;
}

p {
	margin-bottom: 30px;
}

img {
	max-width: 100%;
	height: auto;
}

pre {
	background: var(--white-color);
	padding: 15px;
	border: 1px solid var(--grey-color);
}

hr {
	margin: 0;
	padding: 0px;
	border-bottom: 1px solid #e0e0e0;
	border-top: 0px;
}

b,
strong {
	font-weight: 600;
}

/*+++++++++++++ Lists (Nested) ++++++++++++++*/
ol,
ul {
	padding-left: 25px;
	margin-bottom: 1em;
}

ol li {
	list-style: decimal;
}

ol ol {
	padding-left: 25px;
}

ul li {
	list-style: inherit;
}

/*+++++++++++++ Definition Lists ++++++++++++++*/
dl dd {
	margin-bottom: 15px;
}

dl dd:last-child {
	margin-bottom: 0px;
}

/*+++++++++++++ Table ++++++++++++++*/
table {
	border: 2px solid var(--grey-color);
	width: 100%;
	margin-bottom: 20px;
}

table td,
table th {
	border: 2px solid var(--grey-color);
	padding: 8px;
	text-align: center;
}

/*+++++++++++++ Input Textarea ++++++++++++++*/
input,
input.form-control {
	background: var(--grey-color);
	border: 1px solid var(--grey-color);
	color: var(--dark-color);
	width: 100%;
	float: left;
	font-size: 16px;
	font-weight: 400;
	padding: 0 15px;
	height: 54px;
	line-height: 54px;
	outline: none;
	transition: all 0.5s ease-in-out;
	transition: all 0.5s ease-in-out;
	-moz-transition: all 0.5s ease-in-out;
	-ms-transition: all 0.5s ease-in-out;
	-o-transition: all 0.5s ease-in-out;
	-webkit-transition: all 0.5s ease-in-out;
	border-radius: 3px;
}

input::placeholder {
	color: var(----dark-color);
}

input:focus,
input:hover,
textarea:focus,
textarea:hover,
.form-control:focus {
	border-color: var(--primary-color);
	outline: none;
	box-shadow: none;
}

